  public MomentDtos.PageResponse<MomentDtos.MomentResponse> feed(Long viewer,String type,long page,long size){return feed(viewer,type,page,size,true);}
  public MomentDtos.PageResponse<MomentDtos.MomentResponse> feed(Long viewer,String type,long page,long size,boolean consumeExposure){
    size=Math.min(Math.max(size,1),30); page=Math.max(page,1);
    String feedType="RELATED".equalsIgnoreCase(type)?"RELATED":"RECOMMENDED";
    Optional<MomentIdPageCacheDto> cached=page<=MAX_CACHED_LIST_PAGE?cache.getFeed(viewer,feedType,page,size):Optional.empty();
    if(cached.isPresent()){
      Page<Moment> cachedPage=pageFromCache(cached.get());
      if(cachedPage.getRecords().size()==cached.get().ids().size()&&cachedPage.getRecords().stream().allMatch(m->canView(viewer,m)))
        return consumeExposure?feedPage(viewer,feedType,cachedPage):page(viewer,cachedPage);
    }
    Set<Long> blocked=blockedAuthors(viewer); LambdaQueryWrapper<Moment> q=new LambdaQueryWrapper<Moment>()
      .eq(Moment::getStatus,"PUBLISHED").orderByDesc(Moment::getPublishedAt).orderByDesc(Moment::getId);
    if("RELATED".equals(feedType)){ Set<Long> related=relatedUsers(viewer);if(related.isEmpty())q.eq(Moment::getAuthorUserId,viewer);else q.and(x->x.eq(Moment::getAuthorUserId,viewer).or(y->y.in(Moment::getVisibility,List.of("PUBLIC","RELATED")).in(Moment::getAuthorUserId,related))); }
    else q.and(x->x.eq(Moment::getAuthorUserId,viewer).or().eq(Moment::getVisibility,"PUBLIC"));
    if(!blocked.isEmpty()) q.notIn(Moment::getAuthorUserId,blocked);
    Page<Moment> raw=momentMapper.selectPage(new Page<>(page,size),q);if(page<=MAX_CACHED_LIST_PAGE)cache.putFeed(viewer,feedType,idPage(raw));return consumeExposure?feedPage(viewer,feedType,raw):page(viewer,raw);
  }

  public List<MomentDtos.MomentResponse> hot(Long viewer,long limit){
    int normalized=(int)Math.min(Math.max(limit,1),10);
    List<Long> candidates=loadWithRebuildGuard(cache.getHotMomentIds(),"hot-moments","global",
      Duration.ofSeconds(8),cache::getHotMomentIds,()->momentMapper.selectHotCandidateIds(HOT_CANDIDATE_LIMIT),cache::putHotMomentIds);
    if(candidates.isEmpty())return List.of();
    Map<Long,Moment> moments=momentMapper.selectByIds(candidates).stream().collect(java.util.stream.Collectors.toMap(Moment::getId,m->m));
    List<Moment> visible=new ArrayList<>();
    for(Long id:candidates){Moment moment=moments.get(id);if(moment!=null&&canView(viewer,moment)){visible.add(moment);if(visible.size()==normalized)break;}}
    return responses(viewer,visible);
  }

  public MomentDtos.PageResponse<MomentDtos.MomentResponse> search(Long viewer,String keyword,long page,long size){
    if(!StringUtils.hasText(keyword)) throw bad("请输入搜索关键词");
    String term=keyword.trim();String normalizedTopic=normalizeTopic(term);
    List<Long> matchingTopicIds=StringUtils.hasText(normalizedTopic)?topicMapper.selectList(
      new LambdaQueryWrapper<MomentTopic>().like(MomentTopic::getNormalizedName,normalizedTopic))
      .stream().map(MomentTopic::getId).filter(Objects::nonNull).toList():List.of();
    List<Long> matchingMomentIds=matchingTopicIds.isEmpty()?List.of():relationMapper.selectList(
      new LambdaQueryWrapper<MomentTopicRelation>().in(MomentTopicRelation::getTopicId,matchingTopicIds))
      .stream().map(MomentTopicRelation::getMomentId).filter(Objects::nonNull).distinct().toList();
    size=Math.min(Math.max(size,1),30); page=Math.max(page,1); Set<Long> blocked=blockedAuthors(viewer);
    LambdaQueryWrapper<Moment> q=new LambdaQueryWrapper<Moment>().eq(Moment::getStatus,"PUBLISHED")
      .and(x->x.eq(Moment::getAuthorUserId,viewer).or().eq(Moment::getVisibility,"PUBLIC").or(y->y.eq(Moment::getVisibility,"RELATED").in(Moment::getAuthorUserId,relatedUsersOrMinus(viewer))))
      .and(x->{x.like(Moment::getTitle,term).or().like(Moment::getContent,term);if(!matchingMomentIds.isEmpty())x.or().in(Moment::getId,matchingMomentIds);})
      .orderByDesc(Moment::getPublishedAt).orderByDesc(Moment::getId);
    if(!blocked.isEmpty()) q.notIn(Moment::getAuthorUserId,blocked); return page(viewer,momentMapper.selectPage(new Page<>(page,size),q));
  }

  public MomentDtos.MomentResponse detail(Long viewer,Long id){ Moment m=requireMoment(id); assertVisible(viewer,m); MomentViewerStateCacheDto viewerState=viewerStates(viewer,List.of(id)).getOrDefault(id,MomentViewerStateCacheDto.empty());java.util.Optional<MomentBaseCacheDto> cached=cache.getMoment(id); if(cached.isPresent()) return buildFromCache(viewer,m,cached.get(),viewerState); MomentDtos.MomentResponse response=toResponse(viewer,m,true,viewerState); cache.putMoment(id,extractBaseDto(m,response)); return response; }
  public MomentDtos.AvailabilityResponse availability(Long viewer,Long id){if(auxiliaryCache.isMomentMissing(id))return new MomentDtos.AvailabilityResponse(false,"MOMENT_UNAVAILABLE","帖子不见了");Moment m=momentMapper.selectById(id);if(m==null){auxiliaryCache.markMomentMissing(id);return new MomentDtos.AvailabilityResponse(false,"MOMENT_UNAVAILABLE","帖子不见了");}if(!canView(viewer,m))return new MomentDtos.AvailabilityResponse(false,"MOMENT_UNAVAILABLE","帖子不见了");return new MomentDtos.AvailabilityResponse(true,"AVAILABLE",null);}

  public MomentDtos.PageResponse<MomentDtos.MomentResponse> byTopic(Long viewer,Long topicId,long page,long size){
    MomentTopic topic=topicMapper.selectById(topicId); if(topic==null) throw notFound("话题不存在");
    size=Math.min(Math.max(size,1),30); page=Math.max(page,1);
    Optional<MomentIdPageCacheDto> cached=page<=MAX_CACHED_LIST_PAGE?cache.getTopicMoments(viewer,topicId,page,size):Optional.empty();
    if(cached.isPresent()){Page<Moment> cachedPage=pageFromCache(cached.get());if(cachedPage.getRecords().size()==cached.get().ids().size()&&cachedPage.getRecords().stream().allMatch(m->canView(viewer,m)))return page(viewer,cachedPage);}
    List<Long> ids=relationMapper.selectList(new LambdaQueryWrapper<MomentTopicRelation>().eq(MomentTopicRelation::getTopicId,topicId)).stream().map(MomentTopicRelation::getMomentId).toList();
    if(ids.isEmpty()) return empty(page,size);
    Set<Long> blocked=blockedAuthors(viewer);Collection<Long> related=relatedUsersOrMinus(viewer);
    LambdaQueryWrapper<Moment> q=new LambdaQueryWrapper<Moment>().in(Moment::getId,ids).eq(Moment::getStatus,"PUBLISHED")
      .and(x->x.eq(Moment::getAuthorUserId,viewer).or().eq(Moment::getVisibility,"PUBLIC").or(y->y.eq(Moment::getVisibility,"RELATED").in(Moment::getAuthorUserId,related)))
      .notIn(!blocked.isEmpty(),Moment::getAuthorUserId,blocked).orderByDesc(Moment::getPublishedAt).orderByDesc(Moment::getId);
    Page<Moment> raw=momentMapper.selectPage(new Page<>(page,size),q);if(page<=MAX_CACHED_LIST_PAGE)cache.putTopicMoments(viewer,topicId,idPage(raw));return page(viewer,raw);
  }

  public List<MomentDtos.TopicResponse> suggestTopics(String query){return topicsPage(query,1,10).records();}
  public List<MomentDtos.AuthorResponse> searchMentionUsers(Long viewer,String query){if(!StringUtils.hasText(query))return List.of();String normalized=query.trim();return auxiliaryCache.getMentionSearch(normalized).orElseGet(()->{List<MomentDtos.AuthorResponse> loaded=userMapper.selectList(new LambdaQueryWrapper<User>().eq(User::getStatus,1).like(User::getNickname,normalized).orderByAsc(User::getNickname).last("limit 20")).stream().map(this::authorAndCache).toList();auxiliaryCache.putMentionSearch(normalized,loaded);return loaded;});}
  public MomentDtos.UserCardResponse userCard(Long viewer,Long userId){User user=requireUser(userId);boolean self=Objects.equals(viewer,userId);boolean phoneVisible=self||!Boolean.FALSE.equals(user.getShowPhone());return new MomentDtos.UserCardResponse(user.getId(),user.getNickname(),user.getAvatarUrl(),user.getRole(),"SHOP".equals(user.getRole()),phoneVisible?user.getPhone():null,phoneVisible,self);}
  public MomentDtos.TopicResponse topicDetail(Long id){return auxiliaryCache.getTopic(id).orElseGet(()->{MomentTopic topic=topicMapper.selectById(id);if(topic==null)throw notFound("话题不存在");MomentDtos.TopicResponse response=topicResponse(topic);auxiliaryCache.putTopic(id,response);return response;});}
  public MomentDtos.PageResponse<MomentDtos.TopicResponse> topicsPage(String query,long page,long size){page=Math.max(1,page);size=Math.min(Math.max(1,size),10);String q=query==null?"":normalizeTopic(query);if(StringUtils.hasText(q)){Optional<TopicSearchCacheDto> cached=auxiliaryCache.getTopicSearch(q,page,size);if(cached.isPresent()){TopicSearchCacheDto value=cached.get();return new MomentDtos.PageResponse<>(value.records(),value.page(),value.pageSize(),value.total(),value.hasMore());}}Comparator<MomentDtos.TopicResponse> mutableRank=Comparator.comparingLong(MomentDtos.TopicResponse::momentCount).thenComparingLong(MomentDtos.TopicResponse::userCount).reversed();if(StringUtils.hasText(q))mutableRank=Comparator.comparing((MomentDtos.TopicResponse topic)->!normalizeTopic(topic.name()).equals(q)).thenComparing(mutableRank);final Comparator<MomentDtos.TopicResponse> rank=mutableRank;List<MomentDtos.TopicResponse> all;if(!StringUtils.hasText(q)){all=loadWithRebuildGuard(cache.getHotTopics(),"hot-topics","global",Duration.ofSeconds(8),cache::getHotTopics,()->topicMapper.selectList(null).stream().map(this::topicResponseCached).sorted(rank).toList(),cache::putHotTopics);}else all=topicMapper.selectList(new LambdaQueryWrapper<MomentTopic>().like(MomentTopic::getNormalizedName,q)).stream().map(this::topicResponseCached).sorted(rank).toList();int from=(int)Math.min(all.size(),(page-1)*size),to=(int)Math.min(all.size(),from+size);MomentDtos.PageResponse<MomentDtos.TopicResponse> response=new MomentDtos.PageResponse<>(all.subList(from,to),page,size,all.size(),to<all.size());if(StringUtils.hasText(q))auxiliaryCache.putTopicSearch(q,new TopicSearchCacheDto(response.records(),page,size,response.total(),response.hasMore()));return response;}
  @Transactional public MomentDtos.TopicResponse createTopic(Long userId,String raw){String name=cleanTopic(raw);if(!StringUtils.hasText(name)||name.length()>50)throw bad("话题名称需为1到50个字符");String normalized=normalizeTopic(name);MomentTopic old=topicMapper.selectOne(new LambdaQueryWrapper<MomentTopic>().eq(MomentTopic::getNormalizedName,normalized));if(old!=null)return topicResponseCached(old);MomentTopic t=new MomentTopic();t.setName(name);t.setNormalizedName(normalized);t.setCreatedByUserId(userId);t.setUsageCount(0L);t.setCreatedAt(LocalDateTime.now());try{topicMapper.insert(t);}catch(DuplicateKeyException e){t=topicMapper.selectOne(new LambdaQueryWrapper<MomentTopic>().eq(MomentTopic::getNormalizedName,normalized));}cache.evictHotTopics();auxiliaryCache.evictTopicSearches();MomentDtos.TopicResponse response=topicResponse(t);auxiliaryCache.putTopic(t.getId(),response);return response;}

  @Transactional public MomentDtos.MomentResponse create(Long userId,MomentDtos.UpsertRequest r){
    validate(r); validateReference(userId,r.shopId(),r.dishId()); Moment m=new Moment(); apply(m,r); m.setAuthorUserId(userId); LocalDateTime now=LocalDateTime.now(); m.setCreatedAt(now); m.setUpdatedAt(now); if("PUBLISHED".equals(m.getStatus()))m.setPublishedAt(now); momentMapper.insert(m);auxiliaryCache.evictMomentMissing(m.getId()); replaceTopics(m.getId(),userId,r.topics());MomentQuote quote=replaceQuote(userId,m.getId(),r);Set<Long> mentions=replaceMomentMentions(m.getId(),r.mentionedUserIds());if("PUBLISHED".equals(m.getStatus())){invalidatePublishedMoment(m,topicIds(m.getId()));notifyMomentMentions(m,userId,mentions);notifyQuote(m,userId,quote);pushMomentEvent(m,"PUBLISHED",userId);} return toResponseFresh(userId,momentMapper.selectById(m.getId()));
  }
  @Transactional public MomentDtos.MomentResponse update(Long userId,Long id,MomentDtos.UpsertRequest r){
    Moment m=requireOwned(userId,id); validate(r); validateReference(userId,r.shopId(),r.dishId());
    boolean wasDraft="DRAFT".equals(m.getStatus());
    List<Long> oldTopics=topicIds(id);Set<Long> oldMentions=mentionedUsers(id);String oldQuote=quoteKey(quoteMapper.selectById(id));
    String oldTitle=m.getTitle(),oldContent=m.getContent(),oldVisibility=m.getVisibility(),oldStatus=m.getStatus(),oldImages=m.getImageUrls();
    Long oldShopId=m.getShopId(),oldDishId=m.getDishId();
    apply(m,r);
    boolean imageChanged=!Objects.equals(oldImages,m.getImageUrls());
    boolean nonImageScalarChanged=!Objects.equals(oldTitle,m.getTitle())||!Objects.equals(oldContent,m.getContent())
        ||!Objects.equals(oldVisibility,m.getVisibility())||!Objects.equals(oldStatus,m.getStatus())
        ||!Objects.equals(oldShopId,m.getShopId())||!Objects.equals(oldDishId,m.getDishId());
    boolean scalarChanged=nonImageScalarChanged||imageChanged;
    LocalDateTime now=LocalDateTime.now();
    boolean legacyImageCompletion=!nonImageScalarChanged&&imageChanged&&!StringUtils.hasText(oldImages)
        &&StringUtils.hasText(m.getImageUrls())&&m.getPublishedAt()!=null
        &&!now.isAfter(m.getPublishedAt().plusSeconds(30));
    boolean meaningfulScalarChanged=scalarChanged&&!legacyImageCompletion;
    m.setEditedAt(wasDraft?null:(meaningfulScalarChanged?now:m.getEditedAt()));m.setUpdatedAt(now);
    if(wasDraft&&"PUBLISHED".equals(m.getStatus()))m.setPublishedAt(now);
    momentMapper.updateById(m);
    replaceTopics(id,userId,r.topics());MomentQuote quote=replaceQuote(userId,id,r);Set<Long> mentions=replaceMomentMentions(id,r.mentionedUserIds());
    List<Long> newTopics=topicIds(id);boolean relationChanged=!new HashSet<>(oldTopics).equals(new HashSet<>(newTopics))
        ||!oldMentions.equals(mentions)||!Objects.equals(oldQuote,quoteKey(quote));
    if(!wasDraft&&!meaningfulScalarChanged&&relationChanged){m.setEditedAt(now);momentMapper.updateById(m);}
    Set<Long> affectedTopics=new HashSet<>(oldTopics);affectedTopics.addAll(newTopics);cache.evictMoment(id);cache.evictTopicMoments(affectedTopics);cache.evictHotTopics();cache.evictHotMomentIds();cache.evictUserFeeds(userId);cache.evictUserMoments(userId);cache.evictUnread(relatedUsers(userId));if("PUBLISHED".equals(m.getStatus())){Set<Long> recipients=wasDraft?mentions:new HashSet<>(mentions);if(!wasDraft)recipients.removeAll(oldMentions);notifyMomentMentions(m,userId,recipients);if(wasDraft||!Objects.equals(oldQuote,quoteKey(quote)))notifyQuote(m,userId,quote);if(wasDraft)pushMomentEvent(m,"PUBLISHED",userId);else if(scalarChanged||relationChanged)pushMomentEvent(m,"UPDATED",userId);} return toResponseFresh(userId,momentMapper.selectById(id));
  }
  @Transactional public void delete(Long userId,Long id){ Moment m=requireOwned(userId,id);List<Long> topicIds=topicIds(id);momentMapper.deleteById(id);auxiliaryCache.markMomentMissing(id);topicIds.forEach(this::recomputeTopicUsage);cache.evictMoment(id);invalidatePublishedMoment(m,topicIds); }
  public MomentDtos.PageResponse<MomentDtos.MomentResponse> drafts(Long userId,long page,long size){ size=Math.min(Math.max(size,1),30); page=Math.max(page,1); return page(userId,momentMapper.selectPage(new Page<>(page,size),new LambdaQueryWrapper<Moment>().eq(Moment::getAuthorUserId,userId).eq(Moment::getStatus,"DRAFT").orderByDesc(Moment::getUpdatedAt))); }

  @Transactional public MomentDtos.MomentResponse like(Long userId,Long id,boolean active){ Moment m=requirePublishedVisible(userId,id); MomentLike old=likeMapper.selectOne(new LambdaQueryWrapper<MomentLike>().eq(MomentLike::getMomentId,id).eq(MomentLike::getUserId,userId)); if(active&&old==null){ MomentLike x=new MomentLike();x.setMomentId(id);x.setUserId(userId);x.setCreatedAt(LocalDateTime.now());try{likeMapper.insert(x);}catch(DuplicateKeyException ignored){} notifyAuthor(m,userId,"MOMENT_LIKED","动态通知","赞了你的动态"+m.getTitle(),null); } else if(!active&&old!=null){likeMapper.deleteById(old.getId());} cache.evictInteraction(id);cache.evictViewerStates(userId,List.of(id));pushMomentEvent(m,active?"LIKED":"LIKE_REMOVED",userId); return toResponseFresh(userId,m); }
  @Transactional public MomentDtos.MomentResponse react(Long userId,Long id,String emoji,boolean active){ Moment m=requirePublishedVisibleForUpdate(userId,id); String e=emoji==null?"":emoji.trim();if(e.isEmpty()||e.length()>32)throw bad("请选择有效 emoji"); MomentReaction old=reactionMapper.selectOne(new LambdaQueryWrapper<MomentReaction>().eq(MomentReaction::getMomentId,id).eq(MomentReaction::getUserId,userId).eq(MomentReaction::getEmoji,e));if(active&&old==null){MomentReaction x=new MomentReaction();x.setMomentId(id);x.setUserId(userId);x.setEmoji(e);x.setCreatedAt(LocalDateTime.now());try{reactionMapper.insert(x);}catch(DuplicateKeyException ignored){}notifyReactionAuthor(m,userId);}else if(!active&&old!=null){reactionMapper.deleteById(old.getId());}cache.evictInteraction(id);cache.evictViewerStates(userId,List.of(id));pushMomentEvent(m,active?"REACTED":"REACTION_REMOVED",userId);return toResponseFresh(userId,m);}

  public MomentDtos.PageResponse<MomentDtos.CommentResponse> comments(Long viewer,Long momentId,long page,long size){ Moment m=requirePublishedVisible(viewer,momentId); size=Math.min(Math.max(size,1),10);page=Math.max(page,1);if(page==1){Optional<MomentIdPageCacheDto> cached=cache.getFirstComments(momentId,size);if(cached.isPresent()){Map<Long,MomentComment> found=commentMapper.selectByIds(cached.get().ids()).stream().collect(java.util.stream.Collectors.toMap(MomentComment::getId,c->c));if(found.size()==cached.get().ids().size()){List<MomentComment> ordered=cached.get().ids().stream().map(found::get).toList();List<MomentDtos.CommentResponse> records=commentResponses(viewer,m,ordered,true);return new MomentDtos.PageResponse<>(records,1,size,cached.get().total(),cached.get().hasMore());}}}Page<MomentComment> p=commentMapper.selectPage(new Page<>(page,size),new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getMomentId,momentId).isNull(MomentComment::getParentCommentId).orderByAsc(MomentComment::getCreatedAt).orderByAsc(MomentComment::getId));if(page==1)cache.putFirstComments(momentId,new MomentIdPageCacheDto(p.getRecords().stream().map(MomentComment::getId).toList(),1,size,p.getTotal(),p.hasNext()));return new MomentDtos.PageResponse<>(commentResponses(viewer,m,p.getRecords(),true),page,size,p.getTotal(),p.hasNext()); }
  public MomentDtos.CommentResponse commentForShare(Long viewer,Long momentId,Long commentId){Moment m=requirePublishedVisible(viewer,momentId);MomentComment c=requireComment(commentId);if(!momentId.equals(c.getMomentId()))throw bad("评论不属于该动态");return commentResponse(viewer,m,c,false);}
  public MomentDtos.PageResponse<MomentDtos.CommentResponse> replies(Long viewer,Long commentId,long page,long size){MomentComment root=requireComment(commentId);Moment m=requirePublishedVisible(viewer,root.getMomentId());Long parent=root.getParentCommentId()==null?root.getId():root.getParentCommentId();size=Math.min(Math.max(size,1),10);page=Math.max(page,1);Page<MomentComment> p=commentMapper.selectPage(new Page<>(page,size),new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getParentCommentId,parent).orderByAsc(MomentComment::getCreatedAt).orderByAsc(MomentComment::getId));return new MomentDtos.PageResponse<>(commentResponses(viewer,m,p.getRecords(),false),page,size,p.getTotal(),p.hasNext());}
  @Transactional public MomentDtos.CommentResponse addComment(Long userId,Long momentId,MomentDtos.CommentRequest r){Moment m=requirePublishedVisible(userId,momentId);if(!StringUtils.hasText(r.content())&&(r.imageUrls()==null||r.imageUrls().isEmpty()))throw bad("评论内容或图片不能为空");MomentComment parent=null;if(r.parentCommentId()!=null){parent=requireComment(r.parentCommentId());if(!parent.getMomentId().equals(momentId))throw bad("回复不属于该动态");}if(parent==null&&r.replyToCommentId()!=null)throw bad("回复评论必须指定所属评论线程");MomentComment replyTo=r.replyToCommentId()==null?parent:requireComment(r.replyToCommentId());if(replyTo!=null&&!replyTo.getMomentId().equals(momentId))throw bad("回复目标不属于该动态");Long rootId=parent==null?null:(parent.getParentCommentId()==null?parent.getId():parent.getParentCommentId());if(replyTo!=null){Long replyRoot=replyTo.getParentCommentId()==null?replyTo.getId():replyTo.getParentCommentId();if(!Objects.equals(rootId,replyRoot))throw bad("回复目标不属于同一评论线程");}MomentComment c=new MomentComment();c.setMomentId(momentId);c.setAuthorUserId(userId);c.setParentCommentId(rootId);c.setReplyToCommentId(replyTo==null?null:replyTo.getId());c.setContent(trim(r.content()));c.setImageUrls(writeList(r.imageUrls()));c.setCreatedAt(LocalDateTime.now());c.setUpdatedAt(c.getCreatedAt());commentMapper.insert(c);auxiliaryCache.evictCommentMissing(c.getId());Set<Long> mentions=replaceCommentMentions(c.getId(),r.mentionedUserIds());if(replyTo==null||!replyTo.getAuthorUserId().equals(m.getAuthorUserId()))notifyAuthor(m,userId,"MOMENT_COMMENTED","动态通知","评论了你的动态"+m.getTitle()+"："+preview(c.getContent()),c.getId());if(replyTo!=null&&!replyTo.getAuthorUserId().equals(userId))notify(replyTo.getAuthorUserId(),userId,"MOMENT_COMMENT_REPLIED","动态通知","回复了你在"+m.getTitle()+"下的"+preview(replyTo.getContent())+"："+preview(c.getContent()),m.getId(),c.getId());notifyCommentMentions(m,c,userId,mentions);cache.evictInteraction(momentId);pushMomentEvent(m,"COMMENTED",userId);return commentResponse(userId,m,c,false);}
  @Transactional public void deleteComment(Long userId,Long id){MomentComment c=requireComment(id);if(!c.getAuthorUserId().equals(userId))throw forbidden("只能删除自己的评论");commentMapper.deleteById(id);auxiliaryCache.markCommentMissing(id);cache.evictInteraction(c.getMomentId());Moment m=momentMapper.selectById(c.getMomentId());if(m!=null)pushMomentEvent(m,"COMMENT_DELETED",userId);}
  @Transactional public MomentDtos.CommentResponse likeComment(Long userId,Long id,boolean active){MomentComment c=requireComment(id);Moment m=requirePublishedVisible(userId,c.getMomentId());MomentCommentLike old=commentLikeMapper.selectOne(new LambdaQueryWrapper<MomentCommentLike>().eq(MomentCommentLike::getCommentId,id).eq(MomentCommentLike::getUserId,userId));if(active&&old==null){MomentCommentLike x=new MomentCommentLike();x.setCommentId(id);x.setUserId(userId);x.setCreatedAt(LocalDateTime.now());try{commentLikeMapper.insert(x);}catch(DuplicateKeyException ignored){}if(!c.getAuthorUserId().equals(userId))notify(c.getAuthorUserId(),userId,"MOMENT_COMMENT_LIKED","动态通知","赞了你在"+m.getTitle()+"下的评论："+preview(c.getContent()),m.getId(),c.getId());}else if(!active&&old!=null){commentLikeMapper.deleteById(old.getId());}auxiliaryCache.evictCommentLike(userId,id);cache.evictInteraction(c.getMomentId());pushMomentEvent(m,active?"COMMENT_LIKED":"COMMENT_LIKE_REMOVED",userId);return commentResponse(userId,m,c,false,Map.of(id,active));}

