  @Transactional public MomentDtos.PreferenceResponse updatePreference(Long userId,Long target,MomentDtos.PreferenceRequest r){if(userId.equals(target))throw bad("不能对自己设置");requireUser(target);MomentUserPreference p=findPreference(userId,target);if(p==null){p=new MomentUserPreference();p.setUserId(userId);p.setTargetUserId(target);p.setHideTargetMoments(false);p.setHideMyMoments(false);p.setCreatedAt(LocalDateTime.now());}if(r.hideTargetMoments()!=null)p.setHideTargetMoments(r.hideTargetMoments());if(r.hideMyMoments()!=null)p.setHideMyMoments(r.hideMyMoments());p.setUpdatedAt(LocalDateTime.now());if(p.getId()==null)preferenceMapper.insert(p);else preferenceMapper.updateById(p);accessCache.invalidatePreference(userId,target);cache.evictViewerFeeds(List.of(userId,target));cache.evictUnread(List.of(userId,target));return new MomentDtos.PreferenceResponse(target,Boolean.TRUE.equals(p.getHideTargetMoments()),Boolean.TRUE.equals(p.getHideMyMoments()));}
