  public MomentDtos.ProfileSummary profile(Long viewer,Long target){User u=requireUser(target);MomentUserPreference mine=findPreference(viewer,target);boolean hidden=mine!=null&&Boolean.TRUE.equals(mine.getHideTargetMoments());String reason=hidden?"您已设置不看Ta动态":profileBlockReason(viewer,target,u);boolean can=reason==null;MomentDtos.PageResponse<MomentDtos.MomentResponse> accessible=can?momentsForProfile(viewer,target,1,3):empty(1,3);return new MomentDtos.ProfileSummary(target,defaultProfileVisibility(u),can,hidden,reason,accessible.total(),accessible.records());}
  public MomentDtos.PageResponse<MomentDtos.MomentResponse> momentsForProfile(Long viewer,Long target,long page,long size){User u=requireUser(target);String reason=profileBlockReason(viewer,target,u);MomentUserPreference mine=findPreference(viewer,target);if(mine!=null&&Boolean.TRUE.equals(mine.getHideTargetMoments()))throw forbidden("您已设置不看Ta动态");if(reason!=null)throw forbidden(reason);size=Math.min(Math.max(size,1),30);page=Math.max(page,1);Optional<MomentIdPageCacheDto> cached=page<=MAX_CACHED_LIST_PAGE?cache.getUserMoments(viewer,target,page,size):Optional.empty();if(cached.isPresent()){Page<Moment> cachedPage=pageFromCache(cached.get());if(cachedPage.getRecords().size()==cached.get().ids().size()&&cachedPage.getRecords().stream().allMatch(m->canView(viewer,m)))return page(viewer,cachedPage);}LambdaQueryWrapper<Moment> q=new LambdaQueryWrapper<Moment>().eq(Moment::getAuthorUserId,target).eq(Moment::getStatus,"PUBLISHED");if(!viewer.equals(target)){if(relatedUsers(viewer).contains(target))q.in(Moment::getVisibility,List.of("PUBLIC","RELATED"));else q.eq(Moment::getVisibility,"PUBLIC");}q.orderByDesc(Moment::getPublishedAt).orderByDesc(Moment::getId);Page<Moment> raw=momentMapper.selectPage(new Page<>(page,size),q);if(page<=MAX_CACHED_LIST_PAGE)cache.putUserMoments(viewer,target,idPage(raw));return page(viewer,raw);}
  @Transactional public MessageDtos.ChatMessageResponse share(Long userId,Long momentId,MomentDtos.ShareRequest r){Moment m=requirePublishedVisible(userId,momentId);assertShareRecipients(userId,r.conversationId(),m);MomentComment c=null;if(r.commentId()!=null){c=requireComment(r.commentId());if(!c.getMomentId().equals(momentId))throw bad("评论不属于该动态");}User a=requireUser(m.getAuthorUserId());MessageDtos.ChatMessageResponse shared=messageService.shareMoment(userId,r.conversationId(),m,c,a.getNickname(),firstImage(m));momentMapper.incrementAppShareCount(momentId);cache.evictInteraction(momentId);return shared;}
  @Transactional public MomentDtos.ShareStatsResponse recordExternalShare(Long viewer,Long momentId,Long commentId){Moment m=requirePublishedVisible(viewer,momentId);if(commentId!=null){MomentComment comment=requireComment(commentId);if(!momentId.equals(comment.getMomentId()))throw bad("评论不属于该动态");}momentMapper.incrementExternalShareCount(momentId);cache.evictInteraction(momentId);Moment updated=momentMapper.selectById(momentId);return shareStats(updated==null?m:updated);}

  public MomentDtos.UnreadResponse unread(Long userId){Optional<Long> cached=cache.getUnread(userId);if(cached.isPresent())return new MomentDtos.UnreadResponse(cached.get());Set<Long> related=relatedUsers(userId);if(related.isEmpty()){cache.putUnread(userId,0);return new MomentDtos.UnreadResponse(0L);}Set<Long> blocked=blockedAuthors(userId);LambdaQueryWrapper<Moment> q=new LambdaQueryWrapper<Moment>().eq(Moment::getStatus,"PUBLISHED").in(Moment::getVisibility,List.of("PUBLIC","RELATED")).in(Moment::getAuthorUserId,related).notIn(!blocked.isEmpty(),Moment::getAuthorUserId,blocked);List<Long> read=readMapper.selectList(new LambdaQueryWrapper<MomentRead>().eq(MomentRead::getUserId,userId)).stream().map(MomentRead::getMomentId).toList();if(!read.isEmpty())q.notIn(Moment::getId,read);long count=momentMapper.selectCount(q);cache.putUnread(userId,count);return new MomentDtos.UnreadResponse(count);}
  @Transactional public MomentDtos.UnreadResponse markRead(Long userId,List<Long> ids){
    List<Long> normalizedIds=ids==null?List.of():ids.stream().filter(Objects::nonNull).distinct().limit(100).toList();
    MomentAccessSnapshot access=accessCache.accessFor(userId);
    if(!normalizedIds.isEmpty()){
      Map<Long,Moment> moments=momentMapper.selectByIds(normalizedIds).stream().collect(java.util.stream.Collectors.toMap(Moment::getId,m->m));
      List<Long> eligibleIds=normalizedIds.stream().filter(id->{
        Moment m=moments.get(id);
        return m!=null&&"PUBLISHED".equals(m.getStatus())
          &&List.of("PUBLIC","RELATED").contains(m.getVisibility())
          &&access.relatedUserIds().contains(m.getAuthorUserId())
          &&!access.blockedAuthorIds().contains(m.getAuthorUserId());
      }).toList();
      Set<Long> existing=eligibleIds.isEmpty()?Set.of():readMapper.selectList(
        new LambdaQueryWrapper<MomentRead>().eq(MomentRead::getUserId,userId).in(MomentRead::getMomentId,eligibleIds))
        .stream().map(MomentRead::getMomentId).filter(Objects::nonNull).collect(java.util.stream.Collectors.toSet());
      for(Long id:eligibleIds){
        if(existing.contains(id))continue;
        MomentRead x=new MomentRead();x.setUserId(userId);x.setMomentId(id);x.setReadAt(LocalDateTime.now());
        try{readMapper.insert(x);}catch(DuplicateKeyException ignored){}
      }
    }
    cache.evictViewerStates(userId,normalizedIds);cache.evictUnread(List.of(userId));
    MomentDtos.UnreadResponse result=computeUnread(userId,access);
    wsPushService.pushToUser(userId,"MOMENT","READ_CHANGED",Map.of("relatedUnreadCount",result.relatedUnreadCount()));
    return result;
  }

  @Scheduled(cron="0 20 3 * * *",zone="Asia/Shanghai") @Transactional public void removeExpiredDrafts(){List<Moment> expired=momentMapper.selectList(new LambdaQueryWrapper<Moment>().eq(Moment::getStatus,"DRAFT").lt(Moment::getUpdatedAt,LocalDateTime.now().minusDays(30)));Set<Long> affected=new HashSet<>();expired.forEach(m->{affected.addAll(topicIds(m.getId()));momentMapper.deleteById(m.getId());});affected.forEach(this::recomputeTopicUsage);}

  private MomentBaseCacheDto extractBaseDto(Moment m, MomentDtos.MomentResponse r) {
    List<MomentBaseCacheDto.ReactionSummary> summaries = r.reactions().stream()
        .map(re -> new MomentBaseCacheDto.ReactionSummary(re.emoji(), re.count())).toList();
    List<MomentBaseCacheDto.TopicSummary> topicSummaries = r.topics().stream()
        .map(t -> new MomentBaseCacheDto.TopicSummary(t.id(), t.name(), t.usageCount(), t.userCount(), t.momentCount())).toList();
    MomentDtos.ReferenceResponse ref = r.reference();
    MomentDtos.QuoteResponse quote = r.quote();
    Long hotCommentId = r.hotComment() == null ? null : r.hotComment().id();
    List<Long> mentionIds = r.mentions() == null ? List.of() : r.mentions().stream().map(MomentDtos.AuthorResponse::id).toList();
    return new MomentBaseCacheDto(1, m.getId(), m.getAuthorUserId(),
        r.author().nickname(), r.author().avatarUrl(), r.author().role(),
        m.getTitle(), m.getContent(), m.getVisibility(), m.getStatus(),
        r.imageUrls(), r.likeCount(), r.commentCount(), r.rootCommentCount(),
        r.shareCount(), r.appShareCount(), r.externalShareCount(), summaries,
        ref == null ? null : ref.shopId(), ref == null ? null : ref.shopName(), ref == null ? null : ref.shopImageUrl(),
        ref == null ? null : ref.dishId(), ref == null ? null : ref.dishName(), ref == null ? null : ref.dishImageUrl(),
        ref == null ? null : ref.dishPrice(), ref == null ? null : ref.dishDescription(), ref == null ? null : ref.dishSalesCount(),
        topicSummaries,
        quote == null ? null : quote.momentId(), quote == null ? null : quote.commentId(),
        quote == null ? null : quote.type(), quote == null ? null : quote.author().id(),
        quote == null ? null : quote.author().nickname(), quote == null ? null : quote.author().avatarUrl(),
        quote == null ? null : quote.author().role(), quote == null ? null : quote.momentTitle(),
        quote == null ? null : quote.content(), quote == null ? null : quote.createdAt(),
        hotCommentId, mentionIds, m.getEditedAt(), m.getPublishedAt(), m.getCreatedAt());
  }

  private MomentDtos.MomentResponse buildFromCache(Long viewer, Moment m, MomentBaseCacheDto c, MomentViewerStateCacheDto viewerState) {
    MomentDtos.AuthorResponse author = new MomentDtos.AuthorResponse(c.authorUserId(), c.authorNickname(), c.authorAvatar(), c.authorRole(), "SHOP".equals(c.authorRole()));
    boolean editable = c.authorUserId().equals(viewer);
    List<MomentDtos.ReactionResponse> reactions = c.reactionSummaries().stream()
        .map(s -> new MomentDtos.ReactionResponse(s.emoji(), s.count(), viewerState.reactionEmojis().contains(s.emoji()))).toList();
    MomentDtos.ReferenceResponse ref = (c.shopId() == null && c.dishId() == null) ? null :
        new MomentDtos.ReferenceResponse(c.shopId(), c.shopName(), c.shopImageUrl(), c.dishId(), c.dishName(), c.dishImageUrl(), c.dishPrice(), c.dishDescription(), c.dishSalesCount());
    List<MomentDtos.TopicResponse> topics = c.topics().stream()
        .map(t -> new MomentDtos.TopicResponse(t.id(), t.name(), t.usageCount(), t.userCount(), t.momentCount())).toList();
    MomentDtos.QuoteResponse quote = buildQuoteFromCache(viewer, c);
    MomentComment hotCommentRow=c.hotCommentId()==null?null:commentMapper.selectById(c.hotCommentId());
    MomentDtos.CommentResponse hotComment=hotCommentRow==null?null:commentResponse(viewer,m,hotCommentRow,true);
    List<MomentDtos.AuthorResponse> mentions=mentionAuthors(c.mentionUserIds());
    return new MomentDtos.MomentResponse(c.id(), author, c.title(), c.content(), c.visibility(), c.status(),
        c.imageUrls(), topics, ref, c.likeCount(), viewerState.liked(), c.commentCount(), c.rootCommentCount(),
        c.shareCount(), c.appShareCount(), c.externalShareCount(), reactions,
        c.editedAt(), c.publishedAt(), c.createdAt(), editable, viewerState.read(), hotComment, quote, mentions);
  }

  private MomentDtos.QuoteResponse buildQuoteFromCache(Long viewer, MomentBaseCacheDto c) {
    if (c.quoteType() == null) return null;
    MomentDtos.AuthorResponse snapshotAuthor = new MomentDtos.AuthorResponse(c.quoteAuthorUserId(), c.quoteAuthorNickname(), c.quoteAuthorAvatar(), c.quoteAuthorRole(), "SHOP".equals(c.quoteAuthorRole()));
    boolean available = false;
    if (c.quotedMomentId() != null) {
      Moment target = momentMapper.selectById(c.quotedMomentId());
      available = target != null && canView(viewer, target);
    }
    return new MomentDtos.QuoteResponse(c.quoteType(), c.quotedMomentId(), c.quotedCommentId(), snapshotAuthor,
        c.quoteMomentTitle(), c.quoteContent(), c.quoteCreatedAt(), available,
        available ? null : "该动态已被设置权限，无法查看详情");
  }

  private void apply(Moment m,MomentDtos.UpsertRequest r){m.setTitle(r.title()==null?"":r.title().trim());m.setContent(r.content()==null?"":r.content().trim());m.setVisibility(r.visibility()==null?"PUBLIC":r.visibility());m.setStatus(r.status()==null?"PUBLISHED":r.status());Dish referenced=r.dishId()==null?null:dishMapper.selectById(r.dishId());m.setShopId(r.shopId()!=null?r.shopId():(referenced==null?null:referenced.getShopId()));m.setDishId(r.dishId());m.setImageUrls(writeList(r.imageUrls()));}
  private void validate(MomentDtos.UpsertRequest r){String status=r.status()==null?"PUBLISHED":r.status();if("PUBLISHED".equals(status)&&(r.title()==null||r.title().trim().length()<3))throw bad("标题至少3个字");if("PUBLISHED".equals(status)&&!StringUtils.hasText(r.content()))throw bad("内容不能为空");if(r.topics()!=null&&r.topics().size()>5)throw bad("最多选择5个话题");}
  private void validateReference(Long userId,Long shopId,Long dishId){Dish dish=null;if(dishId!=null){dish=dishMapper.selectById(dishId);if(dish==null)throw notFound("菜品不存在");if(shopId!=null&&!shopId.equals(dish.getShopId()))throw bad("菜品不属于所选店铺");}Long effectiveShop=shopId!=null?shopId:(dish==null?null:dish.getShopId());Shop shop=effectiveShop==null?null:shopMapper.selectById(effectiveShop);if(effectiveShop!=null&&shop==null)throw notFound("店铺不存在");User author=requireUser(userId);if("SHOP".equals(author.getRole())&&shop!=null&&!userId.equals(shop.getOwnerUserId()))throw forbidden("商家只能关联自己的店铺或菜品");}
  private MomentQuote replaceQuote(Long userId,Long ownerMomentId,MomentDtos.UpsertRequest r){if(r.quotedMomentId()!=null&&r.quotedCommentId()!=null)throw bad("一条动态只能引用一个动态或评论");MomentQuote existing=quoteMapper.selectById(ownerMomentId);boolean unchanged=existing!=null&&(("MOMENT".equals(existing.getQuoteType())&&r.quotedCommentId()==null&&Objects.equals(existing.getQuotedMomentId(),r.quotedMomentId()))||("COMMENT".equals(existing.getQuoteType())&&Objects.equals(existing.getQuotedCommentId(),r.quotedCommentId())));if(unchanged)return existing;quoteMapper.deleteById(ownerMomentId);if(r.quotedMomentId()==null&&r.quotedCommentId()==null)return null;Moment target;MomentComment comment=null;if(r.quotedCommentId()!=null){comment=requireComment(r.quotedCommentId());target=requirePublishedVisible(userId,comment.getMomentId());}else target=requirePublishedVisible(userId,r.quotedMomentId());if(ownerMomentId.equals(target.getId()))throw bad("不能引用当前动态");User quoteAuthor=requireUser(comment==null?target.getAuthorUserId():comment.getAuthorUserId());MomentQuote quote=new MomentQuote();quote.setMomentId(ownerMomentId);quote.setQuoteType(comment==null?"MOMENT":"COMMENT");quote.setQuotedMomentId(target.getId());quote.setQuotedCommentId(comment==null?null:comment.getId());quote.setAuthorUserId(quoteAuthor.getId());quote.setAuthorNickname(quoteAuthor.getNickname());quote.setAuthorAvatarUrl(quoteAuthor.getAvatarUrl());quote.setAuthorRole(quoteAuthor.getRole());quote.setMomentTitle(target.getTitle());quote.setQuotedContent(comment==null?target.getContent():comment.getContent());quote.setQuotedAt(comment==null?(target.getPublishedAt()==null?target.getCreatedAt():target.getPublishedAt()):comment.getCreatedAt());quote.setCreatedAt(LocalDateTime.now());quoteMapper.insert(quote);return quote;}
  private Set<Long> replaceMomentMentions(Long momentId,List<Long> requested){mentionMapper.delete(new LambdaQueryWrapper<MomentMention>().eq(MomentMention::getMomentId,momentId));Set<Long> ids=validMentionUsers(requested);for(Long id:ids){MomentMention mention=new MomentMention();mention.setMomentId(momentId);mention.setUserId(id);mention.setCreatedAt(LocalDateTime.now());mentionMapper.insert(mention);}return ids;}
  private Set<Long> replaceCommentMentions(Long commentId,List<Long> requested){Set<Long> ids=validMentionUsers(requested);for(Long id:ids){MomentCommentMention mention=new MomentCommentMention();mention.setCommentId(commentId);mention.setUserId(id);mention.setCreatedAt(LocalDateTime.now());commentMentionMapper.insert(mention);}return ids;}
  private Set<Long> validMentionUsers(List<Long> requested){Set<Long> ids=new LinkedHashSet<>();if(requested==null)return ids;for(Long id:requested){if(id==null)continue;User user=requireUser(id);if(user.getStatus()!=null&&user.getStatus()!=1)throw bad("被提及用户不可用");ids.add(id);}return ids;}
  private Set<Long> mentionedUsers(Long momentId){return mentionMapper.selectList(new LambdaQueryWrapper<MomentMention>().eq(MomentMention::getMomentId,momentId)).stream().map(MomentMention::getUserId).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));}
  private List<Long> commentMentionedUsers(Long commentId){return commentMentionMapper.selectList(new LambdaQueryWrapper<MomentCommentMention>().eq(MomentCommentMention::getCommentId,commentId)).stream().map(MomentCommentMention::getUserId).distinct().toList();}
  private String quoteKey(MomentQuote quote){return quote==null?null:quote.getQuoteType()+":"+quote.getQuotedMomentId()+":"+quote.getQuotedCommentId();}
  private void replaceTopics(Long momentId,Long userId,List<String> names){Set<Long> affected=new HashSet<>(topicIds(momentId));relationMapper.delete(new LambdaQueryWrapper<MomentTopicRelation>().eq(MomentTopicRelation::getMomentId,momentId));if(names!=null)names.stream().map(this::cleanTopic).filter(StringUtils::hasText).distinct().limit(5).forEach(name->{String normalized=normalizeTopic(name);MomentTopic t=topicMapper.selectOne(new LambdaQueryWrapper<MomentTopic>().eq(MomentTopic::getNormalizedName,normalized));if(t==null){t=new MomentTopic();t.setName(name);t.setNormalizedName(normalized);t.setCreatedByUserId(userId);t.setUsageCount(0L);t.setCreatedAt(LocalDateTime.now());try{topicMapper.insert(t);}catch(DuplicateKeyException e){t=topicMapper.selectOne(new LambdaQueryWrapper<MomentTopic>().eq(MomentTopic::getNormalizedName,normalized));}}MomentTopicRelation rel=new MomentTopicRelation();rel.setMomentId(momentId);rel.setTopicId(t.getId());rel.setCreatedAt(LocalDateTime.now());relationMapper.insert(rel);affected.add(t.getId());});affected.forEach(this::recomputeTopicUsage);}
  private MomentDtos.MomentResponse toResponse(Long viewer,Moment m){return toResponse(viewer,m,true,viewerStatesFromDatabase(viewer,List.of(m.getId())).getOrDefault(m.getId(),MomentViewerStateCacheDto.empty()));}
  private MomentDtos.MomentResponse toResponseFresh(Long viewer,Moment m){return toResponse(viewer,m,false,viewerStatesFromDatabase(viewer,List.of(m.getId())).getOrDefault(m.getId(),MomentViewerStateCacheDto.empty()));}
  private MomentDtos.MomentResponse toResponse(Long viewer,Moment m,boolean useCache,MomentViewerStateCacheDto viewerState){MomentDtos.AuthorResponse a=authorById(m.getAuthorUserId());List<MomentTopic> ts=topics(m.getId());MomentStatsCacheDto stats=useCache?cache.getStats(m.getId()).orElseGet(()->loadAndCacheStats(m)):loadStats(m);List<MomentDtos.ReactionResponse> reactions=stats.reactions().stream().map(e->new MomentDtos.ReactionResponse(e.emoji(),e.count(),viewerState.reactionEmojis().contains(e.emoji()))).toList();Shop refShop=m.getShopId()==null?null:shopMapper.selectById(m.getShopId());Dish d=m.getDishId()==null?null:dishMapper.selectById(m.getDishId());MomentDtos.ReferenceResponse ref=new MomentDtos.ReferenceResponse(refShop==null?null:refShop.getId(),refShop==null?null:refShop.getName(),refShop==null?null:refShop.getCoverImageUrl(),d==null?null:d.getId(),d==null?null:d.getName(),d==null?null:d.getImageUrl(),d==null?null:d.getPrice(),d==null?null:d.getDescription(),d==null?null:d.getSalesCount());MomentDtos.CommentResponse hot=useCache?hotComment(viewer,m):hotCommentFresh(viewer,m);return new MomentDtos.MomentResponse(m.getId(),a,m.getTitle(),m.getContent(),m.getVisibility(),m.getStatus(),readList(m.getImageUrls()),ts.stream().map(this::topicResponseCached).toList(),ref,stats.likeCount(),viewerState.liked(),stats.commentCount(),stats.rootCommentCount(),stats.shareCount(),stats.appShareCount(),stats.externalShareCount(),reactions,m.getEditedAt(),m.getPublishedAt(),m.getCreatedAt(),m.getAuthorUserId().equals(viewer),viewerState.read(),hot,quoteResponse(viewer,quoteMapper.selectById(m.getId())),mentionAuthors(mentionedUsers(m.getId())));}

  private MomentStatsCacheDto loadAndCacheStats(Moment m){return loadWithRebuildGuard(Optional.empty(),"stats",String.valueOf(m.getId()),Duration.ofSeconds(5),()->cache.getStats(m.getId()),()->loadStats(m),stats->cache.putStats(m.getId(),stats));}
  private MomentStatsCacheDto loadStats(Moment m){long likes=likeMapper.selectCount(new LambdaQueryWrapper<MomentLike>().eq(MomentLike::getMomentId,m.getId()));long comments=commentMapper.selectCount(new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getMomentId,m.getId()));long roots=commentMapper.selectCount(new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getMomentId,m.getId()).isNull(MomentComment::getParentCommentId));Map<String,Long> grouped=reactionMapper.selectList(new LambdaQueryWrapper<MomentReaction>().eq(MomentReaction::getMomentId,m.getId())).stream().collect(java.util.stream.Collectors.groupingBy(MomentReaction::getEmoji,java.util.stream.Collectors.counting()));List<MomentBaseCacheDto.ReactionSummary> reactions=grouped.entrySet().stream().map(e->new MomentBaseCacheDto.ReactionSummary(e.getKey(),e.getValue())).toList();MomentDtos.ShareStatsResponse shares=shareStats(m);return new MomentStatsCacheDto(likes,comments,roots,shares.shareCount(),shares.appShareCount(),shares.externalShareCount(),reactions);}
  private MomentDtos.CommentResponse commentResponse(Long viewer,Moment m,MomentComment c,boolean includePreview){return commentResponse(viewer,m,c,includePreview,commentLikeStates(viewer,List.of(c.getId())));}
  private List<MomentDtos.CommentResponse> commentResponses(Long viewer,Moment m,List<MomentComment> comments,boolean includePreview){if(comments==null||comments.isEmpty())return List.of();Map<Long,Boolean> states=commentLikeStates(viewer,comments.stream().map(MomentComment::getId).toList());return comments.stream().map(c->commentResponse(viewer,m,c,includePreview,states)).toList();}
  private MomentDtos.CommentResponse commentResponse(Long viewer,Moment m,MomentComment c,boolean includePreview,Map<Long,Boolean> likeStates){MomentDtos.AuthorResponse a=authorById(c.getAuthorUserId());User reply=c.getReplyToCommentId()==null?null:userForComment(c.getReplyToCommentId());long likes=commentLikeMapper.selectCount(new LambdaQueryWrapper<MomentCommentLike>().eq(MomentCommentLike::getCommentId,c.getId()));boolean liked=Boolean.TRUE.equals(likeStates.get(c.getId()));long replies=commentMapper.selectCount(new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getParentCommentId,c.getId()));Comparator<MomentComment> oldestFirst=Comparator.comparing(MomentComment::getCreatedAt,Comparator.nullsLast(Comparator.naturalOrder())).thenComparing(MomentComment::getId,Comparator.nullsLast(Comparator.naturalOrder()));List<MomentComment> previewRows=includePreview?commentMapper.selectList(new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getParentCommentId,c.getId()).orderByAsc(MomentComment::getCreatedAt).orderByAsc(MomentComment::getId)).stream().sorted(oldestFirst).limit(3).toList():List.of();List<MomentDtos.CommentResponse> preview=commentResponses(viewer,m,previewRows,false);return new MomentDtos.CommentResponse(c.getId(),c.getMomentId(),a,c.getContent(),readList(c.getImageUrls()),c.getParentCommentId(),c.getReplyToCommentId(),reply==null?null:reply.getNickname(),c.getAuthorUserId().equals(m.getAuthorUserId()),c.getAuthorUserId().equals(viewer),likes,liked,replies,preview,c.getCreatedAt(),mentionAuthors(commentMentionedUsers(c.getId())));}
  private Map<Long,Boolean> commentLikeStates(Long viewer,Collection<Long> commentIds){List<Long> ids=commentIds==null?List.of():commentIds.stream().filter(Objects::nonNull).distinct().toList();if(viewer==null||ids.isEmpty())return Map.of();Map<Long,Boolean> result=new LinkedHashMap<>(auxiliaryCache.getCommentLikes(viewer,ids));List<Long> missing=ids.stream().filter(id->!result.containsKey(id)).toList();if(!missing.isEmpty()){Set<Long> liked=commentLikeMapper.selectList(new LambdaQueryWrapper<MomentCommentLike>().eq(MomentCommentLike::getUserId,viewer).in(MomentCommentLike::getCommentId,missing)).stream().map(MomentCommentLike::getCommentId).collect(java.util.stream.Collectors.toSet());Map<Long,Boolean> loaded=new LinkedHashMap<>();missing.forEach(id->loaded.put(id,liked.contains(id)));result.putAll(loaded);auxiliaryCache.putCommentLikes(viewer,loaded);}return result;}
  private MomentDtos.AuthorResponse authorById(Long userId){return auxiliaryCache.getAuthor(userId).orElseGet(()->authorAndCache(requireUser(userId)));}
  private MomentDtos.AuthorResponse authorAndCache(User user){MomentDtos.AuthorResponse response=author(user);auxiliaryCache.putAuthor(user.getId(),response);return response;}
  private List<MomentDtos.AuthorResponse> mentionAuthors(Collection<Long> ids){if(ids==null||ids.isEmpty())return List.of();List<Long> ordered=ids.stream().filter(Objects::nonNull).distinct().toList();Map<Long,MomentDtos.AuthorResponse> found=new LinkedHashMap<>(auxiliaryCache.getAuthors(ordered));List<Long> missing=ordered.stream().filter(id->!found.containsKey(id)).toList();if(!missing.isEmpty()){Map<Long,MomentDtos.AuthorResponse> loaded=userMapper.selectByIds(missing).stream().collect(java.util.stream.Collectors.toMap(User::getId,this::author, (a,b)->a,LinkedHashMap::new));found.putAll(loaded);auxiliaryCache.putAuthors(loaded);}return ordered.stream().map(found::get).filter(Objects::nonNull).toList();}
  private MomentDtos.ShareStatsResponse shareStats(Moment m){return new MomentDtos.ShareStatsResponse(zero(m.getShareCount()),zero(m.getAppShareCount()),zero(m.getExternalShareCount()));}
  private long zero(Long value){return value==null?0L:value;}
  private MomentDtos.QuoteResponse quoteResponse(Long viewer,MomentQuote quote){if(quote==null)return null;Moment target=momentMapper.selectById(quote.getQuotedMomentId());MomentComment comment=quote.getQuotedCommentId()==null?null:commentMapper.selectById(quote.getQuotedCommentId());boolean available=target!=null&&canView(viewer,target)&&(quote.getQuotedCommentId()==null||(comment!=null&&target.getId().equals(comment.getMomentId())));MomentDtos.AuthorResponse snapshotAuthor=new MomentDtos.AuthorResponse(quote.getAuthorUserId(),quote.getAuthorNickname(),quote.getAuthorAvatarUrl(),quote.getAuthorRole(),"SHOP".equals(quote.getAuthorRole()));return new MomentDtos.QuoteResponse(quote.getQuoteType(),quote.getQuotedMomentId(),quote.getQuotedCommentId(),snapshotAuthor,quote.getMomentTitle(),quote.getQuotedContent(),quote.getQuotedAt(),available,available?null:"该动态已被设置权限，无法查看详情");}
  private MomentDtos.CommentResponse hotComment(Long viewer,Moment m){Optional<Long> cached=cache.getHotCommentId(m.getId());if(cached.isPresent()){if(cached.get()==0)return null;MomentComment comment=commentMapper.selectById(cached.get());if(comment!=null&&m.getId().equals(comment.getMomentId()))return commentResponse(viewer,m,comment,true);}MomentComment hot=commentMapper.selectList(new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getMomentId,m.getId()).isNull(MomentComment::getParentCommentId)).stream().max(hotCommentOrdering()).orElse(null);cache.putHotCommentId(m.getId(),hot==null?null:hot.getId());return hot==null?null:commentResponse(viewer,m,hot,true);}
  private MomentDtos.CommentResponse hotCommentFresh(Long viewer,Moment m){return commentMapper.selectList(new LambdaQueryWrapper<MomentComment>().eq(MomentComment::getMomentId,m.getId()).isNull(MomentComment::getParentCommentId)).stream().max(hotCommentOrdering()).map(c->commentResponse(viewer,m,c,true)).orElse(null);}
  private Comparator<MomentComment> hotCommentOrdering(){return Comparator.comparingLong((MomentComment c)->commentLikeMapper.selectCount(new LambdaQueryWrapper<MomentCommentLike>().eq(MomentCommentLike::getCommentId,c.getId()))).thenComparing(MomentComment::getCreatedAt,Comparator.nullsFirst(Comparator.naturalOrder()));}
  private MomentDtos.AuthorResponse author(User u){return new MomentDtos.AuthorResponse(u.getId(),u.getNickname(),u.getAvatarUrl(),u.getRole(),"SHOP".equals(u.getRole()));}
  private List<MomentTopic> topics(Long id){List<Long> ids=relationMapper.selectList(new LambdaQueryWrapper<MomentTopicRelation>().eq(MomentTopicRelation::getMomentId,id)).stream().map(MomentTopicRelation::getTopicId).toList();return ids.isEmpty()?List.of():topicMapper.selectBatchIds(ids);}
  private List<Long> topicIds(Long momentId){return relationMapper.selectList(new LambdaQueryWrapper<MomentTopicRelation>().eq(MomentTopicRelation::getMomentId,momentId)).stream().map(MomentTopicRelation::getTopicId).distinct().toList();}
  private void recomputeTopicUsage(Long topicId){MomentTopic topic=topicMapper.selectById(topicId);if(topic==null)return;List<Long> momentIds=relationMapper.selectList(new LambdaQueryWrapper<MomentTopicRelation>().eq(MomentTopicRelation::getTopicId,topicId)).stream().map(MomentTopicRelation::getMomentId).toList();long users=momentIds.isEmpty()?0:momentMapper.selectByIds(momentIds).stream().filter(m->"PUBLISHED".equals(m.getStatus())).map(Moment::getAuthorUserId).filter(Objects::nonNull).distinct().count();topic.setUsageCount(users);topicMapper.updateById(topic);auxiliaryCache.evictTopic(topicId);auxiliaryCache.evictTopicSearches();}
  private MomentDtos.TopicResponse topicResponse(MomentTopic t){List<Long> ids=relationMapper.selectList(new LambdaQueryWrapper<MomentTopicRelation>().eq(MomentTopicRelation::getTopicId,t.getId())).stream().map(MomentTopicRelation::getMomentId).toList();List<Moment> published=ids.isEmpty()?List.of():momentMapper.selectByIds(ids).stream().filter(m->"PUBLISHED".equals(m.getStatus())).toList();long users=published.stream().map(Moment::getAuthorUserId).distinct().count();return new MomentDtos.TopicResponse(t.getId(),t.getName(),users,users,(long)published.size());}
  private MomentDtos.TopicResponse topicResponseCached(MomentTopic topic){return auxiliaryCache.getTopic(topic.getId()).orElseGet(()->{MomentDtos.TopicResponse response=topicResponse(topic);auxiliaryCache.putTopic(topic.getId(),response);return response;});}
  private Moment requireMoment(Long id){if(auxiliaryCache.isMomentMissing(id))throw notFound("MOMENT_UNAVAILABLE: 帖子不见了");Moment m=momentMapper.selectById(id);if(m==null){auxiliaryCache.markMomentMissing(id);throw notFound("MOMENT_UNAVAILABLE: 帖子不见了");}return m;} private Moment requireOwned(Long uid,Long id){Moment m=requireMoment(id);if(!m.getAuthorUserId().equals(uid))throw forbidden("无权操作该动态");return m;} private Moment requirePublishedVisible(Long uid,Long id){Moment m=requireMoment(id);if(!"PUBLISHED".equals(m.getStatus()))throw notFound("MOMENT_UNAVAILABLE: 帖子不见了");assertVisible(uid,m);return m;} private Moment requirePublishedVisibleForUpdate(Long uid,Long id){Moment m=momentMapper.selectByIdForUpdate(id);if(m==null){auxiliaryCache.markMomentMissing(id);throw notFound("MOMENT_UNAVAILABLE: 帖子不见了");}if(!"PUBLISHED".equals(m.getStatus()))throw notFound("MOMENT_UNAVAILABLE: 帖子不见了");assertVisible(uid,m);return m;}
  private MomentComment requireComment(Long id){if(auxiliaryCache.isCommentMissing(id))throw notFound("评论不存在");MomentComment c=commentMapper.selectById(id);if(c==null){auxiliaryCache.markCommentMissing(id);throw notFound("评论不存在");}return c;} private User requireUser(Long id){User u=userMapper.selectById(id);if(u==null)throw notFound("用户不存在");return u;} private User userForComment(Long id){MomentComment c=commentMapper.selectById(id);return c==null?null:userMapper.selectById(c.getAuthorUserId());}
  private void assertVisible(Long viewer,Moment m){if(!canView(viewer,m))throw forbidden("MOMENT_UNAVAILABLE: 帖子不见了");}
  private void assertShareRecipients(Long sender,Long conversationId,Moment moment){if(conversationId==null)throw bad("请选择会话");List<Long> recipients=conversationMemberMapper.selectList(new LambdaQueryWrapper<ConversationMember>().eq(ConversationMember::getConversationId,conversationId).eq(ConversationMember::getMemberStatus,"ACTIVE").ne(ConversationMember::getUserId,sender)).stream().map(ConversationMember::getUserId).distinct().toList();if("PRIVATE".equals(moment.getVisibility())&&!recipients.isEmpty())throw forbidden("私密动态不能分享到聊天");for(Long recipient:recipients)if(!canView(recipient,moment))throw forbidden("会话中有成员无权查看该动态，无法分享");}
  private boolean canView(Long viewer,Moment m){if(m.getAuthorUserId().equals(viewer))return true;if(!"PUBLISHED".equals(m.getStatus()))return false;MomentAccessSnapshot access=accessCache.accessFor(viewer);if(access.blockedAuthorIds().contains(m.getAuthorUserId()))return false;if("PUBLIC".equals(m.getVisibility()))return true;return "RELATED".equals(m.getVisibility())&&access.relatedUserIds().contains(m.getAuthorUserId());}
  private Set<Long> relatedUsers(Long uid){return new HashSet<>(accessCache.accessFor(uid).relatedUserIds());}
  private Collection<Long> relatedUsersOrMinus(Long uid){Set<Long>x=relatedUsers(uid);return x.isEmpty()?List.of(-1L):x;}
  private Set<Long> blockedAuthors(Long uid){return new HashSet<>(accessCache.accessFor(uid).blockedAuthorIds());}
  private MomentUserPreference findPreference(Long uid,Long target){return preferenceMapper.selectOne(new LambdaQueryWrapper<MomentUserPreference>().eq(MomentUserPreference::getUserId,uid).eq(MomentUserPreference::getTargetUserId,target));}
  private String profileBlockReason(Long viewer,Long target,User u){if(viewer.equals(target))return null;MomentUserPreference their=findPreference(target,viewer);if(their!=null&&Boolean.TRUE.equals(their.getHideMyMoments()))return "对方未向你开放动态";String v=defaultProfileVisibility(u);if("PRIVATE".equals(v))return "对方动态页为私密";if("CHAT_FRIENDS".equals(v)&&!relatedUsers(viewer).contains(target))return "仅互聊好友可见";if("FAMILY".equals(v)&&!sameFamily(viewer,target))return "仅家庭成员可见";return null;}
  private boolean sameFamily(Long a,Long b){Set<Long> first=familyShopIds(a),second=familyShopIds(b);return first.stream().anyMatch(second::contains);}
  private Set<Long> familyShopIds(Long userId){Set<Long> ids=new HashSet<>(familyMemberMapper.selectList(new LambdaQueryWrapper<FamilyMember>().eq(FamilyMember::getUserId,userId).eq(FamilyMember::getStatus,"APPROVED")).stream().map(FamilyMember::getShopId).toList());shopMapper.selectList(new LambdaQueryWrapper<Shop>().eq(Shop::getOwnerUserId,userId)).stream().map(Shop::getId).forEach(ids::add);return ids;}
  private String defaultProfileVisibility(User u){return StringUtils.hasText(u.getMomentProfileVisibility())?u.getMomentProfileVisibility():"PUBLIC";}
  private void notifyAuthor(Moment m,Long actor,String type,String title,String content,Long comment){if(!m.getAuthorUserId().equals(actor))notify(m.getAuthorUserId(),actor,type,title,content,m.getId(),comment);}
  private void notifyReactionAuthor(Moment m,Long actor){if(m.getAuthorUserId().equals(actor))return;List<String> emojis=reactionMapper.selectList(new LambdaQueryWrapper<MomentReaction>().eq(MomentReaction::getMomentId,m.getId()).eq(MomentReaction::getUserId,actor).orderByAsc(MomentReaction::getCreatedAt).orderByAsc(MomentReaction::getId)).stream().map(MomentReaction::getEmoji).filter(StringUtils::hasText).distinct().toList();if(!emojis.isEmpty())notify(m.getAuthorUserId(),actor,"MOMENT_REACTED","动态通知","以"+String.join(" ",emojis)+"回应了你的动态"+m.getTitle(),m.getId(),null);}
  private void notifyMomentMentions(Moment m,Long actor,Collection<Long> users){if(users==null)return;for(Long user:users)if(!user.equals(actor))notifyWithDedupe(user,actor,"MOMENT_MENTIONED","动态通知","在"+m.getTitle()+"里提到了你",m.getId(),null,"MENTION:MOMENT:"+m.getId()+":"+user);}
  private void notifyCommentMentions(Moment m,MomentComment comment,Long actor,Collection<Long> users){if(users==null)return;for(Long user:users)if(!user.equals(actor))notifyWithDedupe(user,actor,"MOMENT_COMMENT_MENTIONED","动态通知","在"+m.getTitle()+"下的"+preview(comment.getContent())+"里提到了你",m.getId(),comment.getId(),"MENTION:COMMENT:"+comment.getId()+":"+user);}
  private void notifyQuote(Moment publishing,Long actor,MomentQuote quote){if(quote==null||quote.getAuthorUserId().equals(actor))return;if("COMMENT".equals(quote.getQuoteType()))notifyWithDedupe(quote.getAuthorUserId(),actor,"MOMENT_COMMENT_QUOTED","动态通知","在"+publishing.getTitle()+"下引用了你在动态"+quote.getMomentTitle()+"下的评论："+preview(quote.getQuotedContent()),publishing.getId(),null,"QUOTE:COMMENT:"+publishing.getId());else notifyWithDedupe(quote.getAuthorUserId(),actor,"MOMENT_QUOTED","动态通知","在"+publishing.getTitle()+"下引用了你的动态："+quote.getMomentTitle(),publishing.getId(),null,"QUOTE:MOMENT:"+publishing.getId());}
  private void notify(Long user,Long actor,String type,String title,String content,Long moment,Long comment){String target=(type.contains("COMMENT")&&comment!=null)?"COMMENT:"+comment:"MOMENT:"+moment;notifyWithDedupe(user,actor,type,title,content,moment,comment,target);}
  private void notifyWithDedupe(Long user,Long actor,String type,String title,String content,Long moment,Long comment,String target){try{Map<String,Object> p=new LinkedHashMap<>();p.put("momentId",moment);p.put("actorUserId",actor);if(comment!=null)p.put("commentId",comment);User actorUser=userMapper.selectById(actor);String actorName=actorUser==null?"用户":actorUser.getNickname();String dedupe=notificationDedupe(actor,target,type);messageService.upsertNotification(user,type,title,actorName+(StringUtils.hasText(content)?content:"与你有新的动态互动"),JSON.writeValueAsString(p),dedupe);}catch(Exception ignored){}}
  private String notificationDedupe(Long actor,String target,String type){return "MOMENT:"+actor+":"+target+":"+type;}
  private <T> MomentDtos.PageResponse<T> empty(long p,long s){return new MomentDtos.PageResponse<>(List.of(),Math.max(1,p),Math.max(1,s),0,false);} private MomentDtos.PageResponse<MomentDtos.MomentResponse> page(Long viewer,Page<Moment> p){return new MomentDtos.PageResponse<>(responses(viewer,p.getRecords()),p.getCurrent(),p.getSize(),p.getTotal(),p.hasNext());}
  private MomentDtos.PageResponse<MomentDtos.MomentResponse> feedPage(Long viewer,String feedType,Page<Moment> raw){List<Moment> records=new ArrayList<>(raw.getRecords());List<Long> ownIds=records.stream().filter(m->viewer.equals(m.getAuthorUserId())).map(Moment::getId).toList();Set<Long> exposed=exposureService.findExposed(viewer,feedType,ownIds);List<Moment> firstExposures=records.stream().filter(m->viewer.equals(m.getAuthorUserId())&&!exposed.contains(m.getId())).toList();if(raw.getCurrent()==1&&!firstExposures.isEmpty()){Set<Long> pinnedIds=new HashSet<>(firstExposures.stream().map(Moment::getId).toList());List<Moment> reordered=new ArrayList<>(firstExposures);records.stream().filter(m->!pinnedIds.contains(m.getId())).forEach(reordered::add);records=reordered;}if(!firstExposures.isEmpty())exposureService.recordExposures(viewer,feedType,firstExposures.stream().map(Moment::getId).toList(),LocalDateTime.now());return new MomentDtos.PageResponse<>(responses(viewer,records),raw.getCurrent(),raw.getSize(),raw.getTotal(),raw.hasNext());}
  private List<MomentDtos.MomentResponse> responses(Long viewer,List<Moment> moments){if(moments.isEmpty())return List.of();List<Long> momentIds=moments.stream().map(Moment::getId).filter(Objects::nonNull).distinct().toList();Map<Long,MomentBaseCacheDto> cached=cache.getMoments(momentIds);Map<Long,MomentViewerStateCacheDto> viewerStates=viewerStates(viewer,momentIds);List<MomentDtos.MomentResponse> result=new ArrayList<>(moments.size());for(Moment moment:moments){MomentViewerStateCacheDto viewerState=viewerStates.getOrDefault(moment.getId(),MomentViewerStateCacheDto.empty());MomentBaseCacheDto base=cached.get(moment.getId());if(base!=null)result.add(buildFromCache(viewer,moment,base,viewerState));else{MomentDtos.MomentResponse response=toResponse(viewer,moment,true,viewerState);cache.putMoment(moment.getId(),extractBaseDto(moment,response));result.add(response);}}return result;}
  private Map<Long,MomentViewerStateCacheDto> viewerStates(Long viewer,Collection<Long> momentIds){List<Long> ids=momentIds==null?List.of():momentIds.stream().filter(Objects::nonNull).distinct().toList();if(viewer==null||ids.isEmpty())return Map.of();Map<Long,MomentViewerStateCacheDto> cached=cache.getViewerStates(viewer,ids);Map<Long,MomentViewerStateCacheDto> result=new LinkedHashMap<>(cached==null?Map.of():cached);List<Long> missing=ids.stream().filter(id->!result.containsKey(id)).toList();if(!missing.isEmpty()){Map<Long,MomentViewerStateCacheDto> loaded=viewerStatesFromDatabase(viewer,missing);result.putAll(loaded);cache.putViewerStates(viewer,loaded);}return result;}
  private Map<Long,MomentViewerStateCacheDto> viewerStatesFromDatabase(Long viewer,Collection<Long> momentIds){List<Long> ids=momentIds==null?List.of():momentIds.stream().filter(Objects::nonNull).distinct().toList();if(viewer==null||ids.isEmpty())return Map.of();Set<Long> liked=likeMapper.selectList(new LambdaQueryWrapper<MomentLike>().eq(MomentLike::getUserId,viewer).in(MomentLike::getMomentId,ids)).stream().map(MomentLike::getMomentId).filter(Objects::nonNull).collect(java.util.stream.Collectors.toSet());Set<Long> read=readMapper.selectList(new LambdaQueryWrapper<MomentRead>().eq(MomentRead::getUserId,viewer).in(MomentRead::getMomentId,ids)).stream().map(MomentRead::getMomentId).filter(Objects::nonNull).collect(java.util.stream.Collectors.toSet());Map<Long,Set<String>> reactions=reactionMapper.selectList(new LambdaQueryWrapper<MomentReaction>().eq(MomentReaction::getUserId,viewer).in(MomentReaction::getMomentId,ids)).stream().filter(x->x.getMomentId()!=null&&StringUtils.hasText(x.getEmoji())).collect(java.util.stream.Collectors.groupingBy(MomentReaction::getMomentId,LinkedHashMap::new,java.util.stream.Collectors.mapping(MomentReaction::getEmoji,java.util.stream.Collectors.toSet())));Map<Long,MomentViewerStateCacheDto> result=new LinkedHashMap<>();for(Long id:ids)result.put(id,new MomentViewerStateCacheDto(1,liked.contains(id),read.contains(id),reactions.getOrDefault(id,Set.of())));return result;}
  private MomentIdPageCacheDto idPage(Page<Moment> page){return new MomentIdPageCacheDto(page.getRecords().stream().map(Moment::getId).toList(),page.getCurrent(),page.getSize(),page.getTotal(),page.hasNext());}
  private Page<Moment> pageFromCache(MomentIdPageCacheDto cached){Page<Moment> page=new Page<>(cached.page(),cached.pageSize(),cached.total());if(cached.ids().isEmpty())return page;Map<Long,Moment> found=momentMapper.selectByIds(cached.ids()).stream().collect(java.util.stream.Collectors.toMap(Moment::getId,m->m));page.setRecords(cached.ids().stream().map(found::get).filter(Objects::nonNull).toList());return page;}
  private MomentDtos.UnreadResponse computeUnread(Long userId){return computeUnread(userId,accessCache.accessFor(userId));}
  private MomentDtos.UnreadResponse computeUnread(Long userId,MomentAccessSnapshot access){Set<Long> related=new HashSet<>(access.relatedUserIds());if(related.isEmpty())return new MomentDtos.UnreadResponse(0L);Set<Long> blocked=new HashSet<>(access.blockedAuthorIds());LambdaQueryWrapper<Moment> q=new LambdaQueryWrapper<Moment>().eq(Moment::getStatus,"PUBLISHED").in(Moment::getVisibility,List.of("PUBLIC","RELATED")).in(Moment::getAuthorUserId,related).notIn(!blocked.isEmpty(),Moment::getAuthorUserId,blocked);List<Long> read=readMapper.selectList(new LambdaQueryWrapper<MomentRead>().eq(MomentRead::getUserId,userId)).stream().map(MomentRead::getMomentId).toList();if(!read.isEmpty())q.notIn(Moment::getId,read);return new MomentDtos.UnreadResponse(momentMapper.selectCount(q));}
  private void invalidatePublishedMoment(Moment moment,Collection<Long> topicIds){cache.evictUserFeeds(moment.getAuthorUserId());cache.evictUserMoments(moment.getAuthorUserId());cache.evictTopicMoments(topicIds);cache.evictHotTopics();cache.evictHotMomentIds();Set<Long> unreadUsers=relatedUsers(moment.getAuthorUserId());unreadUsers.add(moment.getAuthorUserId());cache.evictUnread(unreadUsers);}
  private void pushMomentEvent(Moment m,String action,Long actor){Set<Long> recipients=new HashSet<>();if("PRIVATE".equals(m.getVisibility()))recipients.add(m.getAuthorUserId());else if("RELATED".equals(m.getVisibility())){recipients.add(m.getAuthorUserId());recipients.addAll(relatedUsers(m.getAuthorUserId()));}else userMapper.selectList(new LambdaQueryWrapper<User>().eq(User::getStatus,1)).stream().map(User::getId).forEach(recipients::add);recipients.removeAll(blockedMomentRecipients(m.getAuthorUserId(),recipients));recipients.add(m.getAuthorUserId());recipients.forEach(id->wsPushService.pushToUser(id,"MOMENT",action,Map.of("momentId",m.getId(),"actorUserId",actor,"publishedAt",String.valueOf(m.getPublishedAt()))));}
  private Set<Long> blockedMomentRecipients(Long authorId,Collection<Long> recipients){if(recipients==null||recipients.isEmpty())return Set.of();List<Long> ids=recipients.stream().filter(Objects::nonNull).filter(id->!id.equals(authorId)).distinct().toList();if(ids.isEmpty())return Set.of();Set<Long> blocked=new HashSet<>();preferenceMapper.selectList(new LambdaQueryWrapper<MomentUserPreference>().and(root->root.and(x->x.eq(MomentUserPreference::getUserId,authorId).in(MomentUserPreference::getTargetUserId,ids).eq(MomentUserPreference::getHideMyMoments,true)).or(x->x.in(MomentUserPreference::getUserId,ids).eq(MomentUserPreference::getTargetUserId,authorId).eq(MomentUserPreference::getHideTargetMoments,true)))).forEach(p->{if(authorId.equals(p.getUserId())&&Boolean.TRUE.equals(p.getHideMyMoments()))blocked.add(p.getTargetUserId());else if(authorId.equals(p.getTargetUserId())&&Boolean.TRUE.equals(p.getHideTargetMoments()))blocked.add(p.getUserId());});return blocked;}
  private <T> T loadWithRebuildGuard(Optional<T> initial,String resource,String identity,Duration leaseTime,Supplier<Optional<T>> cacheReader,Supplier<T> loader,Consumer<T> cacheWriter){
    if(initial.isPresent())return initial.get();
    MomentCacheRebuildGuard.Lease lease=rebuildGuard.tryAcquire(resource,identity,leaseTime);
    if(lease.acquired()){
      try{
        Optional<T> secondRead=cacheReader.get();
        if(secondRead.isPresent())return secondRead.get();
        T loaded=loader.get();cacheWriter.accept(loaded);return loaded;
      }finally{rebuildGuard.release(lease);}
    }
    if(lease.status()==MomentCacheRebuildGuard.Lease.Status.BUSY){
      for(int attempt=0;attempt<3;attempt++){
        LockSupport.parkNanos(Duration.ofMillis(20).toNanos());
        Optional<T> retried=cacheReader.get();
        if(retried.isPresent())return retried.get();
      }
    }
    return loader.get();
  }
  private String writeList(List<String>x){try{return x==null||x.isEmpty()?null:JSON.writeValueAsString(x);}catch(Exception e){throw bad("图片列表格式错误");}} private List<String> readList(String x){try{return StringUtils.hasText(x)?JSON.readValue(x,new TypeReference<List<String>>(){}):List.of();}catch(Exception e){return List.of();}} private String firstImage(Moment m){List<String>x=readList(m.getImageUrls());return x.isEmpty()?null:x.get(0);} private String trim(String x){return StringUtils.hasText(x)?x.trim():null;} private String preview(String x){String value=StringUtils.hasText(x)?x.trim():"[图片]";return value.length()>80?value.substring(0,80)+"...":value;} private String cleanTopic(String x){return x==null?"":x.trim().replaceFirst("^#","");} private String normalizeTopic(String x){return cleanTopic(x).toLowerCase(Locale.ROOT);}
  private BusinessException bad(String m){return new BusinessException(ErrorCode.BAD_REQUEST,m);} private BusinessException forbidden(String m){return new BusinessException(ErrorCode.FORBIDDEN,m);} private BusinessException notFound(String m){return new BusinessException(ErrorCode.NOT_FOUND,m);}
